import * as s from "../core/validation/index.js";
import type { EnumSchema } from "../core/validation/schema.js";

/**
 * The cause of the failure. This information is generated by the system and can be useful for
 * diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it
 * lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage
 * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
 */
export const Cause3 = {
  UnhandledDecision: "UNHANDLED_DECISION",
  WorkflowTypeDeprecated: "WORKFLOW_TYPE_DEPRECATED",
  WorkflowTypeDoesNotExist: "WORKFLOW_TYPE_DOES_NOT_EXIST",
  DefaultExecutionStartToCloseTimeoutUndefined: "DEFAULT_EXECUTION_START_TO_CLOSE_TIMEOUT_UNDEFINED",
  DefaultTaskStartToCloseTimeoutUndefined: "DEFAULT_TASK_START_TO_CLOSE_TIMEOUT_UNDEFINED",
  DefaultTaskListUndefined: "DEFAULT_TASK_LIST_UNDEFINED",
  DefaultChildPolicyUndefined: "DEFAULT_CHILD_POLICY_UNDEFINED",
  ContinueAsNewWorkflowExecutionRateExceeded: "CONTINUE_AS_NEW_WORKFLOW_EXECUTION_RATE_EXCEEDED",
  OperationNotPermitted: "OPERATION_NOT_PERMITTED",
} as const;
export type Cause3 = (typeof Cause3)[keyof typeof Cause3] | (string & {});

export const cause3Schema: EnumSchema<Cause3> = s.enumOf<Cause3>(Cause3);
